mapper.select:
        select
        projectItem.*,
        beautyProjects.title,
        items.name,
        items.img
        from project_item projectItem
        left join beauty_projects beautyProjects on projectItem.project_id = beautyProjects.id
		left join items items on projectItem.item_id = items.id

            and projectItem.id = #{id}
            and projectItem.project_id = #{projectId}
            and projectItem.item_id = #{itemId}
            and projectItem.num = #{num}
            and projectItem.create_time = #{createTime}
            and beautyProjects.title like concat('%',#{title},'%')
            and items.name like concat('%',#{name},'%')
            and items.img = #{img}


            limit #{current},#{pageSize}

        select count(*) from project_item projectItem
        left join beauty_projects beautyProjects on projectItem.project_id = beautyProjects.id
		left join items items on projectItem.item_id = items.id

            and projectItem.id = #{id}
            and projectItem.project_id = #{projectId}
            and projectItem.item_id = #{itemId}
            and projectItem.num = #{num}
            and projectItem.create_time = #{createTime}
            and beautyProjects.title like concat('%',#{title},'%')
            and items.name like concat('%',#{name},'%')
            and items.img = #{img}
